 function drawGallery(){galleryList.replaceChildren();(pr.gallery||[]).forEach((url,index)=>{const row=n('div','','v55GalleryRow'),img=n('img');img.src=url.startsWith('photo-')?'https://images.unsplash.com/'+url+'?auto=format&fit=crop&w=300&q=70':url;img.alt='Imagen adicional '+(index+1);const label=n('small',(index+1)+'. '+(url.startsWith('data:')?'Imagen cargada':url.slice(0,60)));const acts=n('div','','recordActions');for(const [caption,d] of [['↑',-1],['↓',1]]){const move=n('button',caption);move.disabled=index+d<0||index+d>=pr.gallery.length;move.onclick=()=>{[pr.gallery[index],pr.gallery[index+d]]=[pr.gallery[index+d],pr.gallery[index]];changed();drawGallery()};acts.append(move)}const remove=n('button','Quitar','danger');remove.onclick=()=>{pr.gallery.splice(index,1);changed();drawGallery()};acts.append(remove);row.append(img,label,acts);galleryList.append(row)})}
