 btn.onclick=()=>{try{window.MPI_CalcRules.validate(config.calcRules||[]);const lines=(config.calcRules||[]).map(r=>{const value=window.MPI_CalcRules.evaluate(r.expression,{area:Number(r.sampleArea)||12,original:Number(r.sampleOriginal)||0,height:3,stud:.407,base:12,needed:13,useful:.96,waste:5,perimeter:14,length:5,width:3,slope:10,sheetLength:3,density:5,cols:4,rows:2,price:15});return r.system+' / '+r.code+' = '+value+' · esperado '+String(r.sampleExpected??'pendiente')});result.textContent=lines.join('\n')||'No existen reglas personalizadas. Se usan las fórmulas originales.';toast('Pruebas de sintaxis y valores correctas. Compara resultados con fichas oficiales.')}catch(e){result.textContent='Error: '+e.message;toast(e.message,true)}};
